const { WalletsApiClient } = require('@crossmint/wallets-sdk');

// Read credentials from environment variables
const CROSSMINT_API_KEY = process.env.CROSSMINT_API_KEY;
const SIGNER_SECRET = process.env.SIGNER_SECRET;

/**
 * Executes a treasury action based on the action type
 * @param {Object} action - The action object with a type field
 * @returns {Promise<Object>} - Result object with success status and relevant data
 */
async function executeTreasuryAction(action) {
    if (!action || !action.type) {
        return { success: false, error: 'Invalid action: missing type field' };
    }

    try {
        switch (action.type) {
            case 'create_wallet':
                return await createWallet(action);
            case 'check_balance':
                return await checkBalance(action);
            case 'mint_receipt':
                return await mintReceipt(action);
            default:
                return { success: false, error: 'Unknown action type' };
        }
    } catch (error) {
        return { 
            success: false, 
            error: error.message || 'Action execution failed' 
        };
    }
}

/**
 * Creates a Crossmint EVM smart wallet for the given userId on the specified chain
 * @param {Object} action - Action object with userId and chain
 * @returns {Promise<Object>} - Result with wallet address and details
 */
async function createWallet(action) {
    const { userId, chain } = action;

    if (!userId || !chain) {
        return { success: false, error: 'Missing required fields: userId, chain' };
    }

    if (!CROSSMINT_API_KEY) {
        return { success: false, error: 'Missing CROSSMINT_API_KEY environment variable' };
    }

    try {
        const crossmintClient = new WalletsApiClient({
            apiKey: CROSSMINT_API_KEY,
        });

        const wallet = await crossmintClient.createWallet({
            type: 'evm-smart-wallet',
            linkedUser: { userId: userId },
            chain: chain,
        });

        return {
            success: true,
            address: wallet.address,
            chain: chain,
            userId: userId
        };
    } catch (error) {
        return {
            success: false,
            error: `Failed to create wallet: ${error.message}`
        };
    }
}

/**
 * Queries the Crossmint API for the wallet balance
 * @param {Object} action - Action object with walletAddress and chain
 * @returns {Promise<Object>} - Result with wallet balance
 */
async function checkBalance(action) {
    const { walletAddress, chain } = action;

    if (!walletAddress || !chain) {
        return { success: false, error: 'Missing required fields: walletAddress, chain' };
    }

    if (!CROSSMINT_API_KEY) {
        return { success: false, error: 'Missing CROSSMINT_API_KEY environment variable' };
    }

    try {
        const crossmintClient = new WalletsApiClient({
            apiKey: CROSSMINT_API_KEY,
        });

        const wallet = await crossmintClient.getWallet(walletAddress);
        const balance = await crossmintClient.getBalance(walletAddress, chain);

        return {
            success: true,
            walletAddress: walletAddress,
            chain: chain,
            balance: balance.toString()
        };
    } catch (error) {
        return {
            success: false,
            error: `Failed to check balance: ${error.message}`
        };
    }
}

/**
 * Mints a "Purchase Receipt" NFT to the given email on polygon-amoy via the Crossmint minting API
 * @param {Object} action - Action object with email and purchaseId
 * @returns {Promise<Object>} - Result with action ID
 */
async function mintReceipt(action) {
    const { email, purchaseId } = action;

    if (!email || !purchaseId) {
        return { success: false, error: 'Missing required fields: email, purchaseId' };
    }

    if (!CROSSMINT_API_KEY) {
        return { success: false, error: 'Missing CROSSMINT_API_KEY environment variable' };
    }

    if (!SIGNER_SECRET) {
        return { success: false, error: 'Missing SIGNER_SECRET environment variable' };
    }

    try {
        // Using Crossmint minting API directly
        const mintResponse = await fetch('https://staging.crossmint.com/api/2022-06-09/nfts', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-API-KEY': CROSSMINT_API_KEY,
            },
            body: JSON.stringify({
                name: `Purchase Receipt - ${purchaseId}`,
                description: `NFT receipt for purchase ${purchaseId}`,
                imageUrl: 'https://example.com/receipt.png',
                recipient: `email:${email}`,
                chain: 'polygon-amoy',
                metadata: {
                    purchaseId: purchaseId,
                    type: 'Purchase Receipt',
                    mintedAt: new Date().toISOString()
                }
            })
        });

        if (!mintResponse.ok) {
            const errorData = await mintResponse.text();
            throw new Error(`Minting API error: ${mintResponse.status} - ${errorData}`);
        }

        const mintData = await mintResponse.json();

        return {
            success: true,
            email: email,
            purchaseId: purchaseId,
            actionId: mintData.id || mintData.actionId || 'unknown'
        };
    } catch (error) {
        return {
            success: false,
            error: `Failed to mint receipt: ${error.message}`
        };
    }
}

